with d as (select value r from jsonb_array_elements($q$[{"notes":["Make ahead: shape the stuffed breads the night before, cover and refrigerate, then bring to room temperature and bake the next morning.","Swap the feta for any cheap cheese on sale, white cheddar or halloumi both work well.","Leftover bread keeps wrapped in foil for 2 days and reheats beautifully in a dry pan."],"id":"c3a2ca71-85e3-4976-bb9a-5e205ac4c701"},{"notes":["Use beef or chicken stock depending on what you have, both work just as well.","If you have fresh Vietnamese herbs like Thai basil or Vietnamese mint, use those instead of or alongside the coriander and dill.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Heat the oil in a large pot over medium-high heat. Add the beef mince, breaking it up as it cooks, until no longer pink, about 4 minutes. Drain any excess fat if needed."},{"text":"Add the onion and garlic, stirring until fragrant, about 1 minute."},{"text":"Add the tomato chunks and stir to combine, cooking for 2 minutes."},{"text":"Pour in the stock and bring to a simmer until the broth is bubbling gently. Add the fish sauce and sugar, stirring to combine."},{"text":"Simmer for about 10 minutes, until the tomato is soft and the broth is flavourful. Taste and adjust seasoning with salt and white pepper as needed."},{"text":"Ladle into bowls and serve hot, topped with fresh coriander and dill if using."}],"id":"9f670f96-31de-4b90-99fc-cef224a78623"},{"notes":["The romesco keeps for three days, covered, in the fridge. Make it ahead if you like.","If you can't find calcots, any large spring onion works, the charring is what matters."],"steps":[{"text":"Char the red capsicums directly over a gas flame or under a hot grill, turning often, until the skin is blackened all over, about 10 minutes. Place in a plastic bag for 5 minutes to steam, then peel away the charred skin. Discard the seeds."},{"text":"While the capsicums cool slightly, toast the bread in a dry pan over medium heat until golden, about 2 minutes each side. Tear into pieces."},{"text":"In a mortar or food processor, pound or blitz the hazelnuts with the garlic and toasted bread until you have a rough paste."},{"text":"Add the peeled capsicums and pound or pulse until you have a chunky sauce. Stir in the vinegar and olive oil. Taste and add salt. The romesco should be thick but spoonable."},{"text":"Trim the calcots, leaving the white and pale green parts. Rinse well."},{"text":"Heat a grill pan or cast-iron frying pan over high heat. Brush the calcots lightly with olive oil and place on the hot pan in a single layer. Char, turning occasionally, until the outside is blackened and the inside is tender, about 12–15 minutes. Work in batches if needed."},{"text":"Transfer the charred calcots to a serving plate. Sprinkle lightly with salt. Serve warm with the romesco sauce for dipping."}],"id":"4749620e-6af2-434e-b8bd-05e8b5ad78f6"},{"notes":["Caponata is best made a day or two ahead, the flavours deepen and marry together. Store in an airtight container in the fridge for up to a week.","Serve it at room temperature or cold, as a side dish, on bruschetta, or alongside grilled fish. Some families add a handful of pine nuts, try a small handful if you like."],"steps":[{"text":"Heat 2 tbsp of the olive oil in a large frying pan over medium-high heat. Working in batches so the eggplant isn't crowded, cook until golden on all sides, about 3–4 minutes per batch. Transfer to a plate as you go. Add the remaining oil if needed."},{"text":"In the same pan, reduce the heat to medium and cook the onion, stirring, until soft and golden, about 5 minutes. Add the garlic and cook for another minute, until fragrant."},{"text":"Stir in the tomato paste and cook for 1 minute. Pour in the crushed tomatoes, vinegar and sugar. Bring to a gentle simmer."},{"text":"Return the eggplant to the pan along with the olives and capers. Stir well. Simmer, uncovered, for 20–25 minutes, stirring occasionally, until the eggplant is very tender and the sauce has thickened and darkened slightly. The flavours should be balanced, sweet, sour and savoury all at once."},{"text":"Taste and adjust the salt, pepper, vinegar or sugar as needed. Serve at room temperature or cold, scattered with fresh parsley if you like."}],"id":"d1197ff0-fcb6-4479-902d-5df622a787ce"},{"notes":["Make sure to use waxy potatoes, floury ones will fall apart. Unpeeled skin holds them together better.","Serve warm or at room temperature, but not cold. The flavours are best when the potatoes are still warm enough to absorb the dressing.","This keeps for a few days, covered, in the fridge. Warm gently before serving again."],"id":"d526568c-d106-47f4-95b5-2a64e4f04e0b"},{"notes":["Store in an airtight tin for up to three days; the custard will firm up further and the flavour will deepen.","If you don't have baking beans, use dried rice or lentils. Make sure the pastry is fully blind-baked or it will be soggy.","For a neater slice, chill the tart for at least 2 hours before serving.","Food safety: The eggs are cooked until just set. For pregnant women, young children, older people or anyone with a weakened immune system, cook them until firm all the way through."],"steps":[{"text":"Make the pastry: rub the cold butter into the flour and salt until it resembles fine breadcrumbs. Mix the egg yolk with the caster sugar and cold water, then stir into the flour mixture until just combined. Knead gently to bring the dough together, wrap in plastic and refrigerate for 20 minutes."},{"text":"Preheat the oven to 180°C. Roll out the pastry between two sheets of baking paper to fit a 23 cm loose-bottomed tart tin. Press it gently into the tin and prick the base with a fork. Line with baking paper and fill with baking beans, then bake blind for 12 minutes. Remove the beans and paper, and bake for another 3 minutes until pale golden."},{"text":"While the pastry bakes, warm the milk with the cinnamon stick over medium heat until steaming, then remove from the heat and let it infuse for 5 minutes. Remove the cinnamon stick and cool slightly."},{"text":"Whisk the eggs with the sugar until pale and thick, about 3 minutes. Sift the cornflour, flour and salt together, then fold into the eggs. Slowly pour in the warm milk, stirring constantly to avoid lumps. Stir in the vanilla extract."},{"text":"Strain the custard through a fine sieve into the warm pastry case, pushing gently through any remaining lumps. Bake for 20 to 25 minutes, until the custard is just set but still trembling slightly in the centre, it will set as it cools."},{"text":"Remove from the oven and let the tart cool completely in the tin. Dust generously with ground cinnamon just before serving."}],"id":"f6f22e7c-fb13-4462-a1ea-f5b1a4a01c12"},{"notes":["Make it a day ahead and reheat gently, the flavours deepen. Just prepare the tempering fresh before serving.","If your pumpkin is watery, simmer a little longer to reduce the liquid to a proper sauce.","Erisseri freezes well for up to a month; thaw and reheat on the stove."],"steps":[{"text":"Toast the coriander seeds, cumin seeds, cloves, cardamom pod and dried red chillies in a dry pan over medium heat, shaking constantly, until fragrant (about 2 minutes). Tip into a bowl and let cool slightly, then grind to a fine powder. Stir in the jaggery."},{"text":"Heat 1 tbsp of the coconut oil in a heavy-bottomed pot over medium heat. Add the pumpkin and green beans, and fry, stirring gently, for 5 minutes until they start to soften at the edges."},{"text":"Sprinkle over the ground spice mixture and turmeric, stir well, and cook for another 2 minutes to let the spices coat everything."},{"text":"Pour in the coconut milk and add enough water so the vegetables are just covered. Bring to a gentle simmer and cook, uncovered, for 20–25 minutes until the pumpkin is completely tender and breaks easily with a spoon, and the beans are soft. Stir occasionally and watch the liquid, it should reduce to a creamy sauce that coats the vegetables."},{"text":"Taste and adjust salt. The curry should taste warm and mellow, with no raw spice edges."},{"text":"Just before serving, heat the remaining coconut oil in a small pan over medium-high heat. When it shimmers, add the mustard seeds and a few curry leaves. Let them crackle and pop for about 30 seconds until the seeds finish jumping and the leaves darken slightly. Pour this tempering (tadka) over the curry and stir through. Serve hot with rice."}],"id":"772ae615-ef9a-4dff-bda1-0472bdab71bd"},{"notes":["If you can't find dried oyster mushrooms, use 100 g dried shiitake instead, or a mix of any dried Chinese mushrooms you have on hand.","The chicken must be cooked through (75°C at the thickest part); check with an instant-read thermometer if unsure.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone. Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking."],"steps":[{"text":"Soak the dried shiitake and oyster mushrooms in 250 ml hot water for 10 minutes until softened. Drain, reserving 125 ml of the soaking liquid. Trim the shiitake stems and halve both types of mushrooms."},{"text":"Pat the chicken breasts dry and place them on a shallow steaming plate that fits in your wok or steamer. Scatter the mushrooms around and under the chicken. Tuck the ginger slices and spring onion pieces beneath and around the chicken."},{"text":"In a small bowl, whisk the soy sauce, sesame oil, neutral oil, and reserved mushroom liquid. Pour evenly over the chicken and mushrooms. Season lightly with salt, the soy is already salty."},{"text":"Fill your wok or steamer base with water so it comes to about 5 cm deep. Bring to a rolling boil over high heat until the water is bubbling vigorously and steam is billowing. Place the steaming plate inside on a stand or trivet, making sure the plate doesn't touch the water."},{"text":"Cover and steam for 12 minutes on high heat. The chicken is done when a skewer inserted into the thickest part meets no resistance, and the juices run clear."},{"text":"Carefully remove the plate using tongs or oven mitts, the steam is hot, once the chicken is cooked through with no pink and the mushrooms are tender. Serve hot in the steaming dish, spooning the aromatic broth over the chicken and mushrooms. Pour any remaining broth into a small bowl to drizzle over rice."}],"id":"6be10260-6be0-4025-a8d4-b533551939ec"},{"notes":["If you can find pandan extract, use a tsp in one portion instead of food colouring for authentic flavour. Gula melaka (coconut sugar) can replace caster sugar for a deeper flavour.","Each layer must set properly before the next, don't rush this. If you pour the next layer onto a runny layer, the colours will muddy.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Preheat the oven to 180°C. Line an 8 × 8 inch square tin with baking paper, letting it hang over the sides."},{"text":"Mix desiccated coconut, coconut milk, caster sugar, plain flour, baking powder, salt and eggs in a bowl until smooth. Divide the mixture into 3 or 4 portions and add a few drops of food colouring to each portion (or leave some plain for white layers), stirring well. Keep each colour in a separate bowl."},{"text":"Pour the first colour into the prepared tin and spread evenly to fill the bottom. Bake for 8 to 10 minutes until just set but still soft, it should not be completely firm."},{"text":"Pour the second colour slowly over the first layer and bake again for 8 to 10 minutes until set."},{"text":"Repeat with the remaining colours, baking each layer for 8 to 10 minutes, until all layers are done."},{"text":"Remove from the oven and let cool completely in the tin on a wire rack, about 30 minutes. The cake should be cool before you try to remove it."},{"text":"Once cool, use the baking paper to lift the cake out of the tin. Cut into small squares with a sharp, lightly oiled knife."},{"text":"Store in an airtight container at room temperature for up to 3 days."}],"id":"ec9d3a5b-e766-4852-9284-f133fa1e734a"},{"notes":["Charcoal or hardwood fire makes a big difference to the flavour. If using a gas barbecue, crank it high and let it preheat for 10 minutes.","Don't move the meat around, let it sit and develop that dark, caramelised crust. That's where the flavour is.","Serve with black beans (feijão), white rice, and farofa, as it's served in Brazil.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Build your fire in a churrasco grill or barbecue, using charcoal or wood. Let it burn down to glowing coals, you want high, consistent heat, not flames. This should take about 15 to 20 minutes."},{"text":"Pat the beef, pork and chicken completely dry with paper towels. This helps them get a proper crust."},{"text":"Oil your grill grates well to stop sticking, then place them about 10 cm above the coals, once the coals are glowing red and covered in a light grey ash, with no flames, and the grates are smoking hot."},{"text":"Season the beef and pork generously with coarse rock salt on both sides just before they hit the grill. Place them directly on the hot grates and cook without moving them for 4 to 5 minutes, until a dark crust forms. Flip, salt the other side, and cook for another 4 to 5 minutes. The meat should be hot inside (use a meat thermometer: 63°C for medium-rare beef, 70°C for pork)."},{"text":"Season the chicken thighs with rock salt and place skin-side down on the grill. Cook for 6 to 7 minutes until the skin is golden and crispy, then flip. Cook for another 6 to 7 minutes until cooked through (75°C inside)."},{"text":"Rest all the meat on a warm plate for 5 minutes before serving. Drizzle with any pan juices, and serve hot with your favourite side, beans, rice, or farofa all work bem (well)."}],"id":"4a7c477b-6d1a-43a9-adbe-60e0eaaa0c8f"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"steps":[{"text":"Heat the oil in a large pot over medium-high heat. Add the onion and cook, stirring, until soft and translucent, about 4 minutes."},{"text":"Stir in the garlic and cook for 30 seconds until fragrant, then add the tomatoes. Simmer for 5 minutes, stirring occasionally, until the tomatoes break down."},{"text":"Add the kidney beans, corn, potato and water. Bring to a simmer, then reduce heat to medium and cook until the potato is tender when pierced with a knife and the liquid has thickened slightly."},{"text":"Cook, stirring occasionally, until the potato is tender, about 12 minutes. The mixture should be thick and saucy."},{"text":"Season with salt and pepper to taste. Serve hot, scattered with fresh coriander if you like."}],"id":"21e02d78-bdbe-4533-bcf7-588a5f521f16"},{"notes":["Make a day ahead: braise the oxtail, cool completely, then refrigerate overnight. The fat will set on top and you can lift it off easily. Reheat gently on the stove before serving, the flavour only improves.","Serve with creamy mash, crusty bread or buttered rice to soak up every drop of gravy.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"id":"ba018a4c-670a-43af-a57d-aea9cac0d145"},{"notes":["Use any leftover roasted or braised meat, beef, pork, lamb or even chicken all work well. Cold roast is traditional.","Stovies keep well; reheat gently with a splash of stock if needed, or it makes a good cold lunch the next day."],"steps":[{"text":"Heat the oil or dripping in a large heavy pot over a medium heat. Add the sliced onions and cook, stirring often, until soft and golden, about 8 minutes."},{"text":"Layer half the potato slices on top of the onions. Scatter the meat over the potatoes, then top with the remaining potatoes."},{"text":"Pour the stock over everything. Sprinkle with thyme, salt and pepper. Bring to a simmer, then reduce the heat to low and cover with a lid, cooking until the potatoes are tender and starting to break down into the stock."},{"text":"Cook gently for 30 to 35 minutes, until the potatoes are tender and have broken down slightly and the liquid has reduced to a thick, creamy sauce. Stir gently a couple of times during cooking."},{"text":"Taste and adjust the seasoning. Serve warm, straight from the pot if you're not bothered with washing extra dishes."}],"id":"362c5c74-eb36-4c22-8924-ce073b8d3b37"},{"notes":["The escovitch tastes even better made an hour or two ahead and served at room temperature.","Any firm white fish works, ask the fishmonger what's fresh that day.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"eab04f11-0f4a-47b3-9016-93402e1b23e4"},{"notes":["The ras keeps in the fridge for up to 2 days covered. Make the puri just before serving so it's hot and crisp.","Use the ripest, sweetest mangoes you can find, Alphonso, Kesar or another fragrant variety work best.","If you don't have Greek yoghurt, use thick plain yoghurt or even mascarpone for a richer version."],"steps":[{"text":"Cut the mangoes into chunks and blend smooth in a food processor or blender. Pass through a fine sieve if you prefer it completely smooth; otherwise leave it rustic, both are good. You want about 500 ml of pulp. If your mangoes are very fibrous, sieve it."},{"text":"Whisk the Greek yoghurt, caster sugar, cardamom powder and salt together in a large bowl until the sugar dissolves completely."},{"text":"Add the mango pulp to the yoghurt mixture and fold together gently until just combined. Taste and add the lemon juice if the mangoes are very sweet. Chill the ras while you make the puri."},{"text":"To make the puri dough: mix the flour and salt in a bowl. Make a well in the centre, add the oil and warm water, and mix with your fingers until a soft, slightly sticky dough forms. Knead lightly for 2 minutes until smooth."},{"text":"Let the dough rest for 10 minutes covered with a damp cloth. Divide into 8 equal pieces and roll each into a ball."},{"text":"On a lightly oiled surface, roll each ball into a thin disc, about 10 cm across. Heat 3 cm of neutral oil in a wide, deep pan to 190°C (a piece of dough should float and puff immediately). Carefully slide one puri into the hot oil and press it down gently with the back of a slotted spoon, it should puff up within seconds. Flip and cook the other side until golden, about 1 minute total. Drain on paper towel. Repeat with the remaining dough."},{"text":"Serve the chilled ras in bowls or small glasses, with the hot puri on the side for dipping or tearing into pieces and stirring through."}],"id":"c452364f-960d-437c-bc3b-84d226ba8682"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;